#include <iostream>
using namespace std;

#include <string>

int evaluatePostfix(string expr) {
    int stack[10];
    int top = -1;
    for (int i = 0; i < expr.length(); i++) {
        char c = expr[i];
        if (c >= '0' && c <= '9') {
            stack[++top] = c - '0';
        } else {
            int right = stack[top--];
            int left = stack[top--];
            int result = 0;
            if (c == '+') {
                result = left + right;
            } else if (c == '-') {
                result = left - right;
            } else if (c == '*') {
                result = left * right;
            } else {
                result = left / right;
            }
            stack[++top] = result;
        }
    }
    return stack[top];
}

int main() {
    cout << evaluatePostfix("23*54*+") << endl;
    return 0;
}
